        const auto& row=detail.summary;std::string text="#"+std::to_string(row.number)+" "+row.title+"\n"+detail.scope->repository.full_name()+"\n"+row.author+" · "+row.state+(row.draft?" · draft":"")+"\n"+row.head_branch+" → "+row.base_branch+"\nReviewed head: "+detail.head+"\nBase: "+detail.base+"\n+"+std::to_string(detail.additions)+" −"+std::to_string(detail.deletions)+" · "+std::to_string(detail.files)+" files\nMergeability: "+detail.mergeability+"\n\nChecks\n";
