        const auto lifetime=shared_from_this();if(busy_||closed_)co_return;busy_=true;enabled(false);const auto cancel=cancellation();const winrt::apartment_context ui_thread;std::string result,error;co_await winrt::resume_background();try{result=operation(*service_,cancel);}catch(const std::exception& failure){error=failure.what();}catch(const winrt::hresult_error&){error="The code hosting response could not be read.";}try{co_await ui_thread;}catch(...){busy_=false;co_return;}busy_=false;if(closed_)co_return;enabled(true);if(error.empty())preview_.Text(winrt::to_hstring(result));else status_.Text(winrt::to_hstring(error));
